namespace sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

using sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Models;

namespace sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Models;

namespace sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Services;

/// <summary>
/// WASM-side implementation that calls the server API.
/// </summary>
public sealed class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Models;
using sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Client.Services;

namespace sv_02f0f63d71cd4d5991f8fc83c0cac6cf.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Memphis, TN",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 3, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Package picked up", "New York, NY", new DateTimeOffset(2026, 6, 28, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Departed facility", "New York, NY", new DateTimeOffset(2026, 6, 28, 14, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Arrived at sort facility", "Memphis, TN", new DateTimeOffset(2026, 6, 29, 6, 15, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit to destination", "Memphis, TN", new DateTimeOffset(2026, 6, 29, 12, 0, 0, TimeSpan.Zero)),
            ]),
        ["TRK-002"] = new Shipment(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 27, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 6, 24, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit", "Portland, OR", new DateTimeOffset(2026, 6, 25, 8, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 27, 7, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 27, 11, 45, 0, TimeSpan.Zero)),
            ]),
        ["TRK-003"] = new Shipment(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 5, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Label created", "Chicago, IL", new DateTimeOffset(2026, 6, 30, 8, 0, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

